CREATE DATABASE ecommerce;

USE ecommerce;

SELECT * FROM cleaned_data;

-- Q1. What is the total sales generated by the business?

SELECT SUM(sales) AS Total_Sales FROM cleaned_data;

-- Q2. What is the total profit generated?

SELECT SUM(profit) AS total_profit FROM cleaned_data;

-- Q3. How many unique orders are there?

SELECT COUNT(DISTINCT Order_ID) FROM cleaned_data;

-- Q4. How many unique customers are there?

SELECT COUNT(DISTINCT Customer_ID) FROM cleaned_data;

-- Q5. What is the total quantity of products sold?

SELECT SUM(Quantity) AS Total_Quantity_Sold FROM cleaned_data;

-- Q6. What is the average sales value per order?

SELECT AVG(Sales) AS Average_Sales_Value FROM cleaned_data;

-- Q7. What is the average profit per order?

SELECT AVG(Profit) AS Total_Profit FROM cleaned_data;

-- Q8. What are the total sales for each category?

SELECT Category,SUM(Sales) AS Total_Sales
FROM cleaned_data
GROUP BY Category;

-- Q9. What is the total profit for each category?

SELECT Category,SUM(Profit) AS Total_Profit
FROM cleaned_data
GROUP BY Category;

-- Q10. Which category has the highest total sales?

WITH sales_data AS (
		SELECT Category,SUM(Sales) AS Total_Sales
        FROM cleaned_data
        GROUP BY Category
        )
        
SELECT Category FROM sales_data
WHERE Total_Sales = (
				SELECT MAX(Total_Sales) FROM sales_data
                );
                
-- Q11. Which category has the highest total profit?

WITH profit_data AS (
		SELECT Category,SUM(Profit) AS Total_Profit
        FROM cleaned_data
        GROUP BY Category
        )
        
SELECT Category FROM profit_data
WHERE Total_Profit = (
				SELECT MAX(Total_Profit) FROM profit_data
                );
                
-- Q12. What are the total sales for each region?

SELECT Region, SUM(Sales) AS Total_Sales
FROM cleaned_data
GROUP BY Region;

-- Q13. What are the total profits for each region?

SELECT Region,SUM(Profit) AS Total_Profit
FROM cleaned_data
GROUP BY Region;

-- Q14. Which region has the highest sales?

WITH region_data AS (
		SELECT Region,SUM(Sales) AS Total_Sales
FROM cleaned_data
GROUP BY Region
)

SELECT Region FROM region_data
WHERE Total_Sales = (
					SELECT MAX(Total_Sales) FROM region_data
                    );
                    
                    
-- Q15. What are the total sales for each customer segment?

SELECT Customer_Segment, SUM(Sales) AS Total_Sales
FROM cleaned_data
GROUP BY Customer_Segment;

-- Q16. What are the total profits for each customer segment?

SELECT Customer_Segment,SUM(Profit) AS Total_Profit
FROM cleaned_data
GROUP BY Customer_Segment;

-- Q17. What are the top 10 products by total sales?

SELECT Product,SUM(Sales) AS Total_Sales
FROM cleaned_data
GROUP BY Product
ORDER BY Total_Sales DESC
LIMIT 10;

-- Q18. What are the top 10 products by total profit?

SELECT Product,SUM(Profit) AS Total_Profit
FROM cleaned_data
GROUP BY Product
ORDER BY Total_Profit DESC
LIMIT 10;

-- Q19. Which products have generated a negative total profit?

SELECT Product,SUM(Profit) AS Total_Negative_Profit
FROM cleaned_data
GROUP BY Product
HAVING Total_Negative_Profit <0;

-- Q20. What is the total quantity sold for each product?

SELECT Product,SUM(Quantity) AS Total_Quantity
FROM cleaned_data
GROUP BY Product;

-- Q21. What is the average discount for each category?

SELECT Category,AVG(Discount) FROM cleaned_data
GROUP BY Category;

-- Q22. Which products have received the highest average discount?

WITH discount_table AS (
		SELECT Product,AVG(Discount) AS average_discount
FROM cleaned_data
GROUP BY Product
)

SELECT Product FROM discount_table
WHERE average_discount = (
					SELECT MAX(average_discount) FROM discount_table
                    );

-- Q23. What are the total sales and profit for each product?

SELECT Product,SUM(Sales) AS Total_Sales,SUM(Profit) AS Total_Profit
FROM cleaned_data
GROUP BY Product;

-- Q24. Which category has the highest average profit margin?

WITH profit_margin_table AS(
			SELECT Category,AVG(Profit_Margin) AS average_profit_margin
FROM cleaned_data
GROUP BY Category
)

SELECT Category
FROM profit_margin_table
WHERE average_profit_margin = (
				SELECT MAX(average_profit_margin) FROM profit_margin_table
                );
                
-- Q25. Who are the top 10 customers by total spending?

SELECT Customer_ID,Customer_Name,SUM(Sales) AS Total_Spending
FROM cleaned_data
GROUP BY Customer_ID,Customer_Name
ORDER BY Total_Spending DESC
LIMIT 10;

-- Q26. Which customers have placed the highest number of orders? 

WITH order_table AS(
SELECT Customer_ID,Customer_Name,COUNT(Customer_ID) AS Order_Number
FROM cleaned_data
GROUP BY Customer_ID,Customer_Name
)

SELECT Customer_ID,Customer_Name,Order_Number
FROM order_table
WHERE Order_Number = (
			SELECT MAX(Order_Number) FROM order_table
            );

-- Q27. What is the average spending per customer?

SELECT Customer_ID,Customer_Name,AVG(Sales) AS average_spending
FROM cleaned_data
GROUP BY Customer_id,Customer_Name;

-- Q28. What is the total sales generated by each customer segment?

SELECT Customer_Segment,SUM(Sales) AS Total_sales
FROM cleaned_data
GROUP BY Customer_Segment;

-- Q29. What is the average order value for each customer segment?

SELECT Customer_Segment,AVG(sales) AS average_order_value 
FROM cleaned_data
GROUP BY Customer_Segment;

-- Q30. Which customers have generated a negative total profit?

SELECT Customer_ID,Customer_Name,SUM(Profit) AS Total_Profit
FROM cleaned_data
GROUP BY Customer_ID,Customer_Name
HAVING Total_Profit < 0;

-- Q31. What are the total sales for each month?

SELECT Order_Month_Name,SUM(Sales) AS Total_Sales
FROM cleaned_data
GROUP BY Order_Month_Name;

-- Q32. What are the total profits for each month?

SELECT Order_Month_Name,SUM(Profit) AS Total_Profit
FROM cleaned_data
GROUP BY Order_Month_Name;

-- Q33. What are the total orders for each month?

SELECT Order_Month_Name,COUNT(Order_ID) AS Total_Orders
FROM cleaned_data
GROUP BY Order_Month_Name;

-- Q34. Which month generated the highest sales?

WITH month_sale AS (
SELECT Order_Month_Name,SUM(Sales) AS Total_Sales
FROM cleaned_data
GROUP BY Order_Month_Name
)

SELECT Order_Month_Name FROM month_sale
WHERE Total_Sales = (
				SELECT MAX(Total_Sales) FROM month_sale
                );
                
-- Q35. Which month generated the highest profit?

With profit_table AS (
		SELECT Order_Month_Name,SUM(Profit) AS Total_Profit
        FROM cleaned_data
        GROUP BY Order_Month_Name
)

SELECT Order_Month_Name FROM profit_table
WHERE Total_Profit = (
			SELECT MAX(Total_Profit) FROM profit_table
            );
            
-- Q36. What are the yearly sales totals?

SELECT Order_year,SUM(Sales) AS yearly_sales_total
FROM cleaned_data
GROUP BY Order_year;

-- Q37. What is the cumulative sales over time?

WITH cumulative_sale AS(
SELECT Order_Month_Name,SUM(Sales) AS Total_Sales
FROM cleaned_data
GROUP BY Order_Month_Name
)

SELECT *,SUM(Total_Sales) OVER(ORDER BY FIELD(Order_Month_Name,
'January',
    'February',
    'March',
    'April',
    'May',
    'June',
    'July',
    'August',
    'September',
    'October',
    'November',
    'December')) AS Cumulative_Total FROM cumulative_sale;
    
-- Q38. How many orders are Delivered, Cancelled, and Returned?

SELECT Order_Status,COUNT(Order_ID) AS Total_Order
FROM cleaned_data
GROUP BY Order_Status;

-- Q39. What percentage of orders are Cancelled?

SELECT ROUND(SUM((Order_Status = 'Cancelled'))/COUNT(ORDER_ID)*100,2) AS percentage_cancelled_order
FROM cleaned_data;

-- Q40. What percentage of orders are Returned?

SELECT ROUND(SUM(Order_Status = 'Returned')/COUNT(Order_ID)*100,2)
AS percentage_returned_order
FROM cleaned_data;

-- Q41. Which payment method is used most frequently?

WITH payment_table AS(
SELECT Payment_Method,COUNT(Order_ID) AS total_number
FROM cleaned_data
GROUP BY Payment_Method
)

SELECT Payment_Method
FROM payment_table
WHERE total_number = (
			SELECT MAX(total_number) FROM payment_table
            );
            
-- Q42. What is the sales amount generated by each payment method?

SELECT Payment_Method,SUM(Sales) AS Total_Sales
FROM cleaned_data
GROUP BY Payment_Method;

-- Q43. What are the top 3 products by sales within each category?

WITH category_sales AS (
SELECT Category,Product,SUM(Sales) AS Total_Sales
FROM cleaned_data
GROUP BY Category,Product
),
second_table AS(
SELECT Category,Product,
	Rank() OVER(PARTITION BY Category ORDER BY Total_Sales DESC)
    AS Top3_Products
    FROM category_sales
)

SELECT * FROM second_table
WHERE Top3_Products IN (1,2,3);

-- Q44. Rank all products by sales within their respective categories?

WITH category_data AS (
SELECT Category,Product,SUM(Sales) AS Total_Sales
FROM cleaned_data
GROUP BY Category,Product
)

SELECT *,
		RANK() OVER(PARTITION BY Category ORDER BY Total_Sales DESC) AS rank_number
FROM category_data;
        
-- Q45. Calculate each category's percentage contribution to total sales?

WITH percentage_sale AS (
SELECT Category,SUM(Sales) AS Total_Sales
FROM cleaned_data
GROUP BY Category
)

SELECT *,
	ROUND(Total_Sales/SUM(Total_Sales) OVER()*100 ,2) AS percentage_contribution
    FROM percentage_sale;
    
-- Q46. Calculate each region's percentage contribution to total sales?    


WITH region_contribution AS (
SELECT Region,SUM(Sales) AS Total_Sales
FROM cleaned_data
GROUP BY Region
)

SELECT *,
		ROUND(Total_Sales/SUM(Total_Sales) OVER() *100,2) AS Region_Contribution
        FROM region_contribution;


-- Q47. Find the month-over-month change in sales?

WITH month_sales AS (
SELECT Order_Month_Name,SUM(Sales) AS Current_Sales
FROM cleaned_data
GROUP BY Order_Month_Name
),
sec_table AS(
SELECT *,
	LAG(Current_Sales) OVER(ORDER BY FIELD(
    Order_Month_Name,
    'January',
    'February',
    'March',
    'April',
    'May',
    'June',
    'July',
    'August',
    'September',
    'October',
    'November',
    'December') ) AS Previous_Sales
FROM month_sales
),
Third_table AS (

SELECT *,
	ROUND((Current_Sales-Previous_Sales)/Previous_Sales * 100,2) AS percentage_change_in_sale
    FROM sec_table
    )
    
SELECT *, CASE
    WHEN percentage_change_in_sale <0 THEN 'Decrease'
    WHEN percentage_change_in_sale >0 THEN 'Increase'
    ELSE 'N/A'
    END AS Sale_Status
    FROM Third_table;
    
-- Q48. Find the top 3 customers within each customer segment based on spending?

WITH customer_segment_spending AS (
SELECT Customer_ID,Customer_Name,Customer_Segment,SUM(Sales) AS Total_Spending
FROM cleaned_data
GROUP BY Customer_ID,Customer_Name,Customer_Segment
),
customer_spend AS (
SELECT *,
	 RANK() OVER(PARTITION BY Customer_Segment ORDER BY Total_Spending DESC) AS rank_num
     FROM customer_segment_spending
     )
     
SELECT * FROM customer_spend
WHERE rank_num IN (1,2,3);

-- Q49. Rank customers based on their total spending?

WITH customer_total_spending AS (
SELECT Customer_Name,Customer_ID,SUM(Sales) AS Total_Spending
FROM cleaned_data
GROUP BY Customer_Name,Customer_ID
)

SELECT *,
	DENSE_RANK() OVER(ORDER BY Total_Spending DESC) AS rank_num
    FROM customer_total_spending;
    
-- Q50. Find customers whose total spending is above the average customer spending?

WITH average_customer_spending AS (
SELECT Customer_ID,Customer_Name,SUM(Sales) AS total_spending
FROM cleaned_data
GROUP BY Customer_ID,Customer_Name
)

SELECT * FROM average_customer_spending
WHERE total_spending > (
			SELECT AVG(total_spending) FROM average_customer_spending
            );
            
-- Q51. Find products whose total profit is above the average product profit?

WITH profit_table AS (
SELECT Product,SUM(Profit) AS total_profit
FROM cleaned_data
GROUP BY Product
)

SELECT * FROM profit_table
WHERE total_profit >(
				SELECT AVG(total_profit) FROM profit_table
                );
                
-- Q52. Identify categories where total sales are higher than the overall average category sales?

WITH categories_sale AS (
SELECT Category,SUM(Sales) AS total_sales
FROM cleaned_data
GROUP BY Category
)

SELECT * FROM categories_sale
WHERE total_sales > (
			SELECT AVG(total_sales) FROM categories_sale
            );
            
-- Q53. Find the highest-selling product for each region?

WITH highest_selling AS (
SELECT Region,Product,SUM(Sales) AS product_total__sale_price
FROM cleaned_data
GROUP BY Region,Product
),
rank_product AS(

SELECT *,
	DENSE_RANK() OVER(PARTITION BY Region ORDER BY product_total__sale_price DESC) AS row_num
    FROM highest_selling
    )
    
SELECT * FROM rank_product
WHERE row_num = 1;

-- Q54. Find the highest-profit product for each category?

WITH highest_profit AS (
SELECT Category,Product,SUM(Profit) AS total_profit
FROM cleaned_data
GROUP BY Category,Product
),
highest_table AS(
SELECT *,
	DENSE_RANK() OVER(PARTITION BY Category ORDER BY total_profit DESC) AS row_num
    FROM highest_profit
)
    
SELECT * FROM highest_table
WHERE row_num = 1;


 
 

    
    
    
    

















               
        


































